      "mainEntity": [
                {
          "@type": "Question",
          "name": "Berapa biaya pelatihan Ahli K3 Umum Kemnaker RI dan BNSP?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Biaya pelatihan Ahli K3 Umum bersertifikasi Kemnaker RI jalur Online\/Blended berkisar antara Rp 6.500.000 hingga Rp 7.500.000, sedangkan jalur Tatap Muka (Offline) di Yogyakarta berkisar antara Rp 8.000.000 hingga Rp 8.500.000 (sudah termasuk akomodasi\/fasilitas kelas). Untuk jalur Sertifikasi Profesi BNSP berkisar antara Rp 4.000.000 hingga Rp 5.000.000. Biaya sudah termasuk pembinaan resmi, modul, ujian, SKP\/Lisensi Kemnaker atau Sertifikat BNSP Garuda Emas."          }
        },                {
          "@type": "Question",
          "name": "Apa saja syarat pendidikan untuk mengikuti pelatihan Ahli K3 Umum?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Sesuai Permenaker No. Per.02\/MEN\/1992, syarat pendidikan minimal untuk memperoleh penunjukan Ahli K3 Umum Kemnaker RI adalah Diploma 3 (D3) atau Sarjana (S1) dari SEMUA JURUSAN (baik teknik maupun non-teknik seperti hukum, ekonomi, komunikasi, dsb). Fresh graduate yang belum bekerja tetap dapat mendaftar dan mengikuti pembinaan hingga lulus ujian."          }
        },                {
          "@type": "Question",
          "name": "Apa perbedaan Ahli K3 Umum sertifikasi Kemnaker RI vs BNSP?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Sertifikasi Kemnaker RI berorientasi pada kepatuhan hukum regulasi nasional dan penunjukan operasional personel di tempat kerja (menghasilkan SKP & Lisensi K3 untuk pembentukan P2K3 dan audit SMK3). Sedangkan sertifikasi BNSP berorientasi pada pengakuan kompetensi profesi kerja berbasis standar SKKNI nasional berlogo Garuda Emas, sangat diminati untuk tender BUMN, KKKS Migas, dan standar kualifikasi kompetensi profesi."          }
        },                {
          "@type": "Question",
          "name": "Berapa lama masa berlaku sertifikat & lisensi Ahli K3 Umum?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Sertifikat Pembinaan Ahli K3 Umum dari Kemnaker RI berlaku seumur hidup. Namun, Lisensi Kewenangan & Surat Keputusan Penunjukan (SKP) berlaku selama 3 (tiga) tahun dan wajib diperpanjang melalui PJK3 resmi sebelum masa berlakunya habis. Sertifikat kompetensi BNSP juga memiliki masa berlaku selama 3 tahun."          }
        },                {
          "@type": "Question",
          "name": "Apakah fresh graduate bisa langsung mengikuti pelatihan AK3U?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Bisa. Fresh graduate lulusan D3 atau S1 dapat langsung mengambil sertifikasi Ahli K3 Umum. Sertifikat ini menjadi nilai tambah terbesar (competitive edge) saat melamar kerja posisi HSE Officer, Safety Supervisor, atau Management Trainee di sektor migas, tambang, manufaktur, dan konstruksi."          }
        },                {
          "@type": "Question",
          "name": "Berapa lama durasi pelatihan Ahli K3 Umum?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Durasi pembinaan Ahli K3 Umum sertifikasi Kemnaker RI adalah 12 hari kerja efektif (sekitar 120 jam pelajaran), mencakup penyampaian materi regulasi & teknis, praktik kerja lapangan (PKL), pembuatan laporan PKL, seminar presentasi, dan evaluasi ujian negara Kemnaker RI. Untuk jalur BNSP berlangsung selama 3–4 hari efektif."          }
        },                {
          "@type": "Question",
          "name": "Apakah Wahana Totalita menyediakan program In-House Training untuk perusahaan?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Ya. Kami menyelenggarakan In-House Training Ahli K3 Umum khusus bagi korporasi atau instansi dengan jadwal fleksibel, materi yang disesuaikan dengan hazard industri perusahaan, serta efisiensi anggaran investasi pelatihan untuk rombongan karyawan."          }
        }              ]
